async function main() {
  const category = await prisma.category.upsert({
    where: { slug: "devops" },
    update: { name: "DevOps", group: "Technology", description: "Reported DevOps, Docker and Kubernetes interview questions and answers." },
    create: { name: "DevOps", slug: "devops", group: "Technology", description: "Reported DevOps, Docker and Kubernetes interview questions and answers." },
  });

  const subcategories = [
    ["DevOps Fundamentals", "devops-fundamentals"],
    ["CI/CD & Git", "cicd-git"],
    ["Terraform & IaC", "terraform-iac"],
    ["Docker", "docker"],
    ["Kubernetes", "kubernetes"],
    ["Cloud & Infrastructure", "cloud-infrastructure"],
    ["Linux & Scripting", "linux-scripting"],
    ["Observability", "observability"],
  ] as const;
  const subcategoryIds = new Map<string, string>();
  for (const [name, slug] of subcategories) {
    const subcategory = await prisma.subcategory.upsert({
      where: { categoryId_slug: { categoryId: category.id, slug } },
      update: { name },
      create: { name, slug, categoryId: category.id },
    });
    subcategoryIds.set(slug, subcategory.id);
  }

  for (const item of questions) {
    const subcategoryId = subcategoryIds.get(item.subcategorySlug);
    if (!subcategoryId) throw new Error(`Missing subcategory: ${item.subcategorySlug}`);
    await prisma.interviewQuestion.upsert({
      where: { slug: item.slug },
      update: {
        question: item.question,
        categoryId: category.id,
        subcategoryId,
        experienceLevel: ExperienceLevel.MID_LEVEL,
        difficulty: Difficulty.MEDIUM,
        interviewType: InterviewType.TECHNICAL,
        shortDescription: item.shortDescription,
        explanation: item.explanation,
        sampleAnswer: item.sampleAnswer,
        detailedAnswer: item.detailedAnswer,
        keyPoints: item.keyPoints,
        commonMistakes: item.commonMistakes,
        followUpQuestions: item.followUpQuestions,
        tags: item.tags,
        isPublished: true,
      },
      create: {
        question: item.question,
        slug: item.slug,
        categoryId: category.id,
        subcategoryId,
        experienceLevel: ExperienceLevel.MID_LEVEL,
        difficulty: Difficulty.MEDIUM,
        interviewType: InterviewType.TECHNICAL,
        shortDescription: item.shortDescription,
        explanation: item.explanation,
        sampleAnswer: item.sampleAnswer,
        detailedAnswer: item.detailedAnswer,
        keyPoints: item.keyPoints,
        commonMistakes: item.commonMistakes,
        followUpQuestions: item.followUpQuestions,
        tags: item.tags,
        isPublished: true,
      },
    });
  }

  console.log(`Imported ${questions.length} reported DevOps/Docker/Kubernetes interview questions.`);
}

main().catch((error) => {
  console.error("DevOps interview seed failed:", error);
  process.exitCode = 1;
}).finally(() => prisma.$disconnect());
